package xnby.replica;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.iemp.endanger.server.hidden.service.CheckInventoryService;
import com.iemp.endanger.server.hidden.entity.CheckInventoryEntity;
import org.springframework.context.*;import org.springframework.context.event.ContextRefreshedEvent;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.aop.*;import org.springframework.aop.framework.Advised;import org.springframework.aop.support.AopUtils;
import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.interceptor.*;
import org.springframework.transaction.TransactionDefinition;
import java.lang.reflect.Method;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Startup-only observation of existing bean/advisor metadata. No business method or endpoint. */
public final class OriginalTransactionObservation implements ApplicationContextInitializer<ConfigurableApplicationContext> {
 public static final String OUTPUT="transaction-bean-observation.json";
 static void require(boolean value,String code){if(!value)throw new IllegalStateException(code);}
 static String sha(byte[] raw)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw));}
 static Path root(String value)throws Exception{
  Path p=Path.of(value).toAbsolutePath().normalize();require(p.toRealPath().equals(p),"CANONICAL_OWN_RUN_REQUIRED");for(Path q=p;q!=null;q=q.getParent())require(!Files.isSymbolicLink(q)&&!Files.isSymbolicLink(q.toRealPath()),"NO_RUN_LINK_ALLOWED");
  require(p.getFileName().toString().equals("b")&&p.getParent().getFileName().toString().matches("j[1-9][0-9]{0,3}")&&p.getParent().getParent().getFileName().toString().equals("runs")&&p.getParent().getParent().getParent().getFileName().toString().equals("OriginalServer")&&p.getParent().getParent().getParent().getParent().getFileName().toString().equals("UserData")&&p.getParent().getParent().getParent().getParent().getParent().getFileName().toString().equals("Application"),"OWN_SERVER_BUSINESS_RUN_LAYOUT_REQUIRED");
  Path owner=p.resolve("server-owner.properties");require(Files.isRegularFile(owner)&&!Files.isSymbolicLink(owner)&&Files.size(owner)<=2048,"SMALL_OWN_OWNER_FILE_REQUIRED");Properties props=new Properties();try(var stream=Files.newInputStream(owner)){props.load(stream);}require("zhumadian.original.server.owner.v1".equals(props.getProperty("schema")),"OWN_OWNER_SCHEMA_REQUIRED");String id=props.getProperty("ownerId");require(id!=null&&UUID.fromString(id).toString().equals(id),"CANONICAL_OWNER_REQUIRED");return p;
 }
 static Map<String,Object> additional(ConfigurableApplicationContext context,String serviceName,String dtoName,List<String> methods)throws Exception{
  Class<?> serviceType=Class.forName(serviceName),dtoType=Class.forName(dtoName);ConfigurableListableBeanFactory factory=context.getBeanFactory();String[] names=factory.getBeanNamesForType(serviceType,false,false);require(names.length<=4,"BOUNDED_ADDITIONAL_SERVICES");List<Object> rows=new ArrayList<>();boolean all=names.length==1;
  for(String name:names){Object bean=factory.getSingleton(name);if(!serviceType.isInstance(bean)){all=false;rows.add(Map.of("beanName",name,"existingSingleton",false));continue;}Class<?> target=AopUtils.getTargetClass(bean);Map<String,Object> row=new LinkedHashMap<>();row.put("beanName",name);row.put("existingSingleton",true);row.put("targetClass",target.getName());row.put("beanClass",bean.getClass().getName());row.put("isAopProxy",AopUtils.isAopProxy(bean));
   try(var in=target.getResourceAsStream("/"+target.getName().replace('.','/')+".class")){require(in!=null,"ADDITIONAL_TARGET_CLASS_BYTES");byte[] raw=in.readNBytes(262145);require(raw.length<=262144,"ADDITIONAL_CLASS_SIZE_BOUND");row.put("targetClassSHA256",sha(raw));}
   Map<String,Object> checks=new LinkedHashMap<>();boolean matched=AopUtils.isAopProxy(bean);
   for(String method:methods){Method m=target.getMethod(method,dtoType);List<Object> details=new ArrayList<>();boolean methodMatched=false;
    if(bean instanceof Advised advised){Advisor[] advisors=advised.getAdvisors();require(advisors.length<=32,"BOUNDED_ADDITIONAL_ADVISORS");for(int i=0;i<advisors.length;i++){Advisor advisor=advisors[i];if(!(advisor.getAdvice() instanceof TransactionInterceptor tx))continue;TransactionAttributeSource source=tx.getTransactionAttributeSource();TransactionAttribute attr=source==null?null:source.getTransactionAttribute(m,target);boolean pointcut=true,runtime=false;
      if(advisor instanceof PointcutAdvisor p){var matcher=p.getPointcut().getMethodMatcher();runtime=matcher.isRuntime();pointcut=p.getPointcut().getClassFilter().matches(target)&&matcher.matches(m,target);}
      boolean metadata=pointcut&&!runtime&&attr!=null&&attr.getPropagationBehavior()==TransactionDefinition.PROPAGATION_REQUIRED&&attr.rollbackOn(new Exception("OWN_METADATA_ONLY_CHECKED_EXCEPTION"));methodMatched|=metadata;details.add(Map.of("advisorIndex",i,"staticPointcutMatches",pointcut,"runtimePointcut",runtime,"metadataMatched",metadata,"directManagerReferencePresent",tx.getTransactionManager()!=null));
    }}checks.put(method,Map.of("matchingExceptionRollbackAdvisor",methodMatched,"advisors",details));matched&=methodMatched;
   }row.put("methods",checks);row.put("allMethodsHaveMatchingTransactionAdvisor",matched);rows.add(row);all&=matched;
  }return Map.of("serviceType",serviceName,"services",rows,"allMethodsHaveMatchingTransactionAdvisor",all,"existingSingletonMetadataOnly",true);
 }
 public void initialize(ConfigurableApplicationContext context){
  String configured=System.getProperty("own.candidate.root");if(configured==null)return;final Path folder;
  try{folder=root(configured);}catch(Exception error){System.err.println("OWN_TRANSACTION_OBSERVATION_OWNER_REJECTED "+error.getClass().getSimpleName());return;}
  AtomicBoolean once=new AtomicBoolean();context.addApplicationListener((ApplicationListener<ContextRefreshedEvent>)event->{if(event.getApplicationContext()!=context||once.get())return;if(context.getBeanFactory().getBeanNamesForType(CheckInventoryService.class,false,false).length==0){System.out.println("OWN_TRANSACTION_OBSERVATION_SKIPPED_CONTEXT_WITHOUT_INVENTORY");return;}if(!once.compareAndSet(false,true))return;try{observe(context,folder);}catch(Exception error){System.err.println("OWN_TRANSACTION_OBSERVATION_FAILED "+error.getClass().getSimpleName());}});
 }
 static void observe(ConfigurableApplicationContext context,Path folder)throws Exception{
  Map<String,Object> extra=new LinkedHashMap<>();
  extra.put("reservation",additional(context,"com.iemp.endanger.server.work.service.WorkReservationBaseService","com.iemp.endanger.server.work.entity.vo.WorkReservationBaseVo",List.of("updateById")));
  extra.put("thirdParty",additional(context,"com.iemp.endanger.server.safetyBasic.service.ThirdPartyUnitInfoService","com.iemp.endanger.server.safetyBasic.entity.vo.ThirdPartyUnitInfoVo",List.of("save","updateById")));
  Properties extraOwner=new Properties();try(var stream=Files.newInputStream(folder.resolve("server-owner.properties"))){extraOwner.load(stream);}
  extra.put("schema","xnby.work-services-transaction-observation.v1");extra.put("PID",ProcessHandle.current().pid());extra.put("run",folder.getParent().getFileName().toString());extra.put("ownerIdSHA256",sha(extraOwner.getProperty("ownerId").getBytes(StandardCharsets.US_ASCII)));extra.put("existingSingletonMetadataOnly",true);extra.put("businessMethodsInvoked",false);extra.put("SQLOrNetworkRequestsIssuedByObserver",false);extra.put("actualRollbackOrHTTPOrAuthenticationVerified",false);
  byte[] extraRaw=new ObjectMapper().writeValueAsBytes(extra);require(extraRaw.length<=65536,"ADDITIONAL_REPORT_SIZE_BOUND");Files.write(folder.resolve("work-services-transaction-observation.json"),extraRaw,StandardOpenOption.CREATE_NEW);
  ConfigurableListableBeanFactory factory=context.getBeanFactory();String[] names=factory.getBeanNamesForType(CheckInventoryService.class,false,false);require(names.length<=4,"BOUNDED_SERVICE_CANDIDATES_REQUIRED");List<Object> services=new ArrayList<>();boolean all=names.length==1;
  for(String name:names){Object bean=factory.getSingleton(name);if(!(bean instanceof CheckInventoryService)){all=false;services.add(Map.of("beanName",name,"existingSingleton",false));continue;}Class<?> target=AopUtils.getTargetClass(bean);Map<String,Object> item=new LinkedHashMap<>();item.put("beanName",name);item.put("beanClass",bean.getClass().getName());item.put("targetClass",target.getName());item.put("isAopProxy",AopUtils.isAopProxy(bean));item.put("existingSingleton",true);String resource="/"+target.getName().replace('.','/')+".class";try(var in=target.getResourceAsStream(resource)){require(in!=null,"TARGET_CLASS_RESOURCE_REQUIRED");byte[] bytes=in.readNBytes(262145);require(bytes.length<=262144,"TARGET_CLASS_RESOURCE_BOUND");item.put("targetClassSHA256",sha(bytes));}
   List<Object> advisors=new ArrayList<>();Map<String,List<Object>> matches=new LinkedHashMap<>();for(String method:List.of("saveDeep","updateDeep","removeDeep"))matches.put(method,new ArrayList<>());
   if(bean instanceof Advised advised){Advisor[] list=advised.getAdvisors();require(list.length<=32,"BOUNDED_ADVISORS_REQUIRED");for(int i=0;i<list.length;i++){Advisor advisor=list[i];var advice=advisor.getAdvice();Map<String,Object> row=new LinkedHashMap<>();row.put("index",i);row.put("advisorClass",advisor.getClass().getName());row.put("adviceClass",advice.getClass().getName());row.put("isTransactionInterceptor",advice instanceof TransactionInterceptor);
    if(advice instanceof TransactionInterceptor tx){TransactionAttributeSource attrs=tx.getTransactionAttributeSource();row.put("attributeSourcePresent",attrs!=null);row.put("directManagerReferencePresent",tx.getTransactionManager()!=null);if(tx.getTransactionManager()!=null)row.put("directManagerClass",tx.getTransactionManager().getClass().getName());
     for(String method:matches.keySet()){Method m=method.equals("removeDeep")?target.getMethod(method,String.class):target.getMethod(method,CheckInventoryEntity.class);TransactionAttribute attr=attrs==null?null:attrs.getTransactionAttribute(m,target);boolean runtimePointcut=false,pointcut=true;if(advisor instanceof PointcutAdvisor p){var matcher=p.getPointcut().getMethodMatcher();runtimePointcut=matcher.isRuntime();pointcut=p.getPointcut().getClassFilter().matches(target)&&matcher.matches(m,target);}
      boolean expected=attr!=null&&attr.getPropagationBehavior()==TransactionDefinition.PROPAGATION_REQUIRED&&attr.rollbackOn(new Exception("OWN_METADATA_ONLY_CHECKED_EXCEPTION"));Map<String,Object> match=new LinkedHashMap<>();match.put("advisorIndex",i);match.put("staticPointcutMatches",pointcut);match.put("runtimePointcut",runtimePointcut);match.put("originalRequiredAndRollbackForException",expected);match.put("qualifier",attr==null?"":Objects.toString(attr.getQualifier(),""));match.put("metadataMatched",pointcut&&!runtimePointcut&&expected);matches.get(method).add(match);}
    }advisors.add(row);
   }}
   boolean methods=true;for(var entry:matches.entrySet())methods&=entry.getValue().stream().anyMatch(x->Boolean.TRUE.equals(((Map<?,?>)x).get("metadataMatched")));item.put("advisors",advisors);item.put("methods",matches);item.put("allThreeMethodsHaveMatchingTransactionAdvisor",methods);all&=AopUtils.isAopProxy(bean)&&methods;services.add(item);
  }
  String[] managerNames=factory.getBeanNamesForType(PlatformTransactionManager.class,false,false);require(managerNames.length<=16,"BOUNDED_TX_MANAGERS_REQUIRED");List<Object> managers=new ArrayList<>();int existing=0;for(String name:managerNames){Object bean=factory.getSingleton(name);boolean found=bean instanceof PlatformTransactionManager;if(found)existing++;Map<String,Object> row=new LinkedHashMap<>();row.put("beanName",name);row.put("existingSingleton",found);if(found)row.put("beanClass",bean.getClass().getName());managers.add(row);}
  Properties owner=new Properties();try(var stream=Files.newInputStream(folder.resolve("server-owner.properties"))){owner.load(stream);}Map<String,Object> report=new LinkedHashMap<>();report.put("schema","xnby.original-transaction-bean-observation.v1");report.put("PID",ProcessHandle.current().pid());report.put("run",folder.getParent().getFileName().toString());report.put("ownerIdSHA256",sha(owner.getProperty("ownerId").getBytes(StandardCharsets.US_ASCII)));report.put("services",services);report.put("existingTransactionManagers",managers);report.put("allThreeMethodsHaveMatchingTransactionAdvisor",all);report.put("existingTransactionManagerCount",existing);report.put("contextRefreshed",true);report.put("contextClass",context.getClass().getName());report.put("parentContextPresent",context.getParent()!=null);report.put("observationScope","context with existing inventory singleton");report.put("existingSingletonMetadataOnly",true);report.put("businessMethodsInvoked",false);report.put("SQLOrNetworkRequestsIssuedByObserver",false);report.put("actualRollbackOrHTTPOrAuthenticationVerified",false);report.put("fullCloneReady",false);byte[] raw=new ObjectMapper().writeValueAsBytes(report);require(raw.length<=65536,"OBSERVATION_SIZE_BOUND");Files.write(folder.resolve(OUTPUT),raw,StandardOpenOption.CREATE_NEW);System.out.println("OWN_TRANSACTION_BEAN_OBSERVATION_WRITTEN serviceCount="+names.length+" matched="+all+" managers="+existing);
 }
}
